/** What the form holds: two Accounts named the way a `<select>` names them, and a typed decimal. */
const aForm = (fromAccountId: string, toAccountId: string, amount: string) => ({
  fromAccountId,
  toAccountId,
  amount,
})

const schema = transferSchemaFor(ACCOUNTS)

